import pandas as pd
import matplotlib.pyplot as plt

# Load the context data generated by your main script
df = pd.read_csv('MPXV_SNPs_3bp.tab', sep='\t', header=None, names=['range', 'context'])

# Count occurrences of each 3-bp motif
context_counts = df['context'].str.upper().value_counts().sort_index()

plt.figure(figsize=(12, 6))
context_counts.plot(kind='bar', color='teal', edgecolor='black')

plt.title('Distribution of 3-bp SNP Contexts in MPXV')
plt.xlabel('Trinucleotide Motif')
plt.ylabel('Frequency')
plt.xticks(rotation=45)
plt.tight_layout()

plt.savefig('mpxv_context_bias.png')
print("Context chart saved as mpxv_context_bias.png")
